// This file adds snapshot-based source tracing: given one validated snapshot
// and a dataset name, it reports every root source reachable from that
// dataset through direct upstream edges, together with one shortest path per
// root. The answer depends only on the snapshot's graph semantics, so a later
// change to the live graph never alters what a frozen version reports.
package chainledger

import (
	"fmt"
)

// SourceTrace links one reachable root source to the path that reaches it.
//
// Path starts at the queried dataset and ends at Root, listing every dataset
// name along the way, both endpoints included. When the queried dataset is
// itself a root, Path is the single-element array holding its own name.
type SourceTrace struct {
	Root string   `json:"root"`
	Path []string `json:"path"`
}

// TraceReport is the deterministic, read-only answer of a source trace
// against one snapshot.
//
// ContentID is the snapshot's own content identifier, Dataset is the queried
// name exactly as given, and Sources lists every reachable root once, sorted
// by root name byte order.
type TraceReport struct {
	ContentID string        `json:"contentId"`
	Dataset   string        `json:"dataset"`
	Sources   []SourceTrace `json:"sources"`
}

// TraceSources traces the root sources of dataset within the graph frozen in
// snap. The snapshot is assumed to have passed ParseSnapshot; it is only read,
// never modified.
//
// The root lookup follows the one root-source rule shared with the snapshot
// comparison (see root_sources.go): both walk the same normalized adjacency
// for "which upstream-less datasets are reachable", so the two reports can
// never explain a root differently. The comparison computes the root-name
// sets only; the trace additionally carries one representative path per
// root.
//
// Every reachable root is reported exactly once with one shortest path (fewest
// direct relations). Among equally short paths the one chosen is the smallest
// when the names are compared element by element from the start of the path in
// UTF-8 byte order. Roots sharing intermediate datasets keep their own paths.
//
// An empty dataset name or a name absent from the snapshot is an error.
func TraceSources(snap *SnapshotFile, dataset string) (*TraceReport, error) {
	if dataset == "" {
		return nil, fmt.Errorf("%w: dataset name to trace must not be empty", ErrInvalidArgument)
	}
	adj := adjacencyFromValidFile(snap.Graph)
	if _, ok := adj[dataset]; !ok {
		return nil, fmt.Errorf("%w: dataset %q is not in the snapshot", ErrNotFound, dataset)
	}

	return &TraceReport{
		ContentID: snap.ContentID,
		Dataset:   dataset,
		Sources:   traceRootSources(dataset, adj),
	}, nil
}

// This file holds the root-source rules behind the two read-only reports a
// frozen snapshot supports:
//
//   - source tracing (TraceSources) lists every root source with one
//     representative SHORTEST PATH per root (traceRootSources), and
//   - snapshot comparison (CompareSnapshots) decides, for each dataset common
//     to two versions, whether the reachable root SET changed (rootSources).
//
// Both ask the same reachability question — "which datasets without upstreams
// are reachable from this one by following direct upstream edges" — but the
// comparison never displays a path: it only compares two root-name sets. The
// two walkers below are therefore deliberately separate. A names-only
// reachability walk is all the comparison needs; it neither selects a
// representative route among several branches nor builds or copies a path for
// any root, so a long derivation chain (or many downstreams sharing one
// upstream segment) never causes trace-shaped slices to be allocated only to
// be thrown away. Tracing still walks with full path state, because its
// report does carry paths. Walking the same normalized adjacency under the
// same root rule keeps the two reports in agreement: a root is reachable for
// the comparison exactly when a trace against the same snapshot lists it.
package chainledger

import "sort"

// rootSources finds, for one dataset within an already validated adjacency,
// the names of every root source reachable by following direct upstream
// edges. It is the comparison-only half of this file: it computes just the
// root-name set, and never builds, chooses, or copies a path, because the
// compare report never carries one.
//
// A dataset that itself has no upstream is a root and its own source, a root
// reached through several branches is reported exactly once, intermediates
// that still have upstreams never qualify, and roots in disconnected
// components are never reached. The result is sorted by name byte order, is
// never nil, and is a fresh slice owned by the caller.
func rootSources(dataset string, adj adjacency) []string {
	// Plain reachability walk along direct upstream edges. Only node identity
	// matters: the first visit marks a node for the rest of the walk, so no
	// per-route state (and no path slices) is ever kept.
	visited := map[string]bool{dataset: true}
	frontier := []string{dataset}
	roots := make([]string, 0)
	for len(frontier) > 0 {
		node := frontier[len(frontier)-1]
		frontier = frontier[:len(frontier)-1]
		parents := adj[node]
		if len(parents) == 0 {
			roots = append(roots, node)
			continue
		}
		for _, parent := range parents {
			if !visited[parent] {
				visited[parent] = true
				frontier = append(frontier, parent)
			}
		}
	}
	sort.Strings(roots)
	return roots
}

// traceRootSources finds, for one dataset within an already validated
// adjacency, every root source reachable by following direct upstream edges:
// a dataset that itself has no upstream is a root and its own source, a root
// reached through several branches is reported exactly once, intermediates
// that still have upstreams never qualify, and roots in disconnected
// components are never reached.
//
// Every root carries one shortest path (fewest direct relations), beginning at
// the queried dataset, listing every intermediate, and ending at the root.
// Among equally short paths the choice is made element by element from the
// START of the path in UTF-8 byte order, at the first differing name — never
// by the last branch name. Roots reached through a shared intermediate each
// keep their own complete path. The returned entries are sorted by root name
// byte order, and every path is a fresh slice owned by the caller, so editing
// a returned report can never reach the adjacency or another report.
func traceRootSources(dataset string, adj adjacency) []SourceTrace {
	// Breadth-first walk from the queried dataset along direct upstream
	// edges. best[node] holds the shortest, tie-broken path from the query to
	// node; because every edge has the same weight, the first level at which
	// a node is reached is its shortest distance, and keeping only the
	// smallest candidate path per node preserves the global minimum.
	best := map[string][]string{dataset: {dataset}}
	frontier := []string{dataset}
	for len(frontier) > 0 {
		candidates := make(map[string][]string)
		for _, node := range frontier {
			for _, parent := range adj[node] {
				if _, seen := best[parent]; seen {
					continue
				}
				path := append(append([]string{}, best[node]...), parent)
				if current, ok := candidates[parent]; !ok || pathLess(path, current) {
					candidates[parent] = path
				}
			}
		}
		next := make([]string, 0, len(candidates))
		for node, path := range candidates {
			best[node] = path
			next = append(next, node)
		}
		frontier = next
	}

	sources := make([]SourceTrace, 0)
	for node, path := range best {
		if len(adj[node]) == 0 {
			sources = append(sources, SourceTrace{Root: node, Path: path})
		}
	}
	sort.Slice(sources, func(i, j int) bool { return sources[i].Root < sources[j].Root })
	return sources
}

// pathLess compares two equal-purpose paths element by element from the start
// using plain string (UTF-8 byte) order, deciding on the first differing
// name. A strict prefix counts as smaller, matching lexicographic order.
func pathLess(a, b []string) bool {
	for i := 0; i < len(a) && i < len(b); i++ {
		if a[i] != b[i] {
			return a[i] < b[i]
		}
	}
	return len(a) < len(b)
}

// Package chainledger implements the on-chain data governance core.
package chainledger

import (
	"errors"
	"fmt"
	"sort"
)

// Sentinel errors so callers can recognize rejection reasons with errors.Is.
var (
	// ErrInvalidArgument is returned for malformed requests (empty names,
	// nil lineage nodes referenced as upstreams).
	ErrInvalidArgument = errors.New("invalid argument")
	// ErrNotFound is returned when an upstream dataset is not registered.
	ErrNotFound = errors.New("not found")
	// ErrCycle is returned when applying the registration would form a cycle.
	ErrCycle = errors.New("cycle detected")
	// ErrNotInitialized is returned when the graph map itself is nil.
	ErrNotInitialized = errors.New("lineage graph is not initialized")
)

// Dataset is one ingestible on-chain data source with a declared schema version.
type Dataset struct {
	Name          string
	SchemaVersion int
	Rows          int
	Upstreams     []string
}

// Lineage records where a dataset came from, so every derived table can be traced.
// Parents and Children are always sorted by name and free of duplicates.
type Lineage struct {
	Dataset  string
	Parents  []string
	Children []string
}

// Register links a dataset into the lineage graph.
//
// Registering an existing dataset name REPLACES its direct upstream (parent)
// relationships with the given parents:
//   - downstream (child) relationships of the dataset are preserved;
//   - parents dropped from the list no longer list the dataset as a child;
//   - newly added parents list the dataset exactly once;
//   - a nil or empty parents slice removes every direct upstream, turning the
//     dataset into a root while keeping its downstream.
//
// Duplicate parent names count as one relationship, and the stored lineage is
// independent of the caller's slice: mutating parents after Register returns
// does not affect the graph.
//
// The relationship change is determined solely by the submitted dataset name
// and its new upstreams. A hand-constructed graph may have two independent
// Lineage records whose Children (or Parents) slices share one backing array,
// overlap in a sub-slice window, or carry spare capacity another record's
// list occupies. Such a graph is legal as long as names correspond and no
// reference or cycle is missing, so Register never edits those name lists in
// place: a parent list that gains or loses the dataset receives a freshly
// allocated, independent slice (see withName and withoutName). Removing one
// upstream can therefore never shift or duplicate names another record's
// list shares, and adding one can never overwrite a name living in spare
// capacity. Records of datasets not involved in the change keep their
// previous contents.
//
// Registration is atomic. If any parent is missing or the resulting graph
// would contain a cycle (including a dataset depending on itself, directly or
// through other nodes), no node and no parent/child record is changed. Cycle
// validation uses the relationships as they will be AFTER the replacement, so
// an edge removed by this registration cannot make a legal change fail.
func Register(graph map[string]*Lineage, dataset Dataset, parents []string) error {
	if graph == nil {
		return fmt.Errorf("%w: create the graph map with make before registering datasets", ErrNotInitialized)
	}
	if dataset.Name == "" {
		return fmt.Errorf("%w: dataset name is required", ErrInvalidArgument)
	}

	// Normalize on a copy: dedupe (duplicates are one relationship), sort,
	// and detach from the caller's backing array.
	wanted := uniqueSorted(parents)
	for _, parent := range wanted {
		entry, ok := graph[parent]
		if !ok {
			return fmt.Errorf("%w: upstream dataset %q is not registered", ErrNotFound, parent)
		}
		if entry == nil {
			return fmt.Errorf("%w: upstream dataset %q points to a nil lineage node", ErrInvalidArgument, parent)
		}
	}

	// Snapshot the relationships this commit changes on independent slices
	// BEFORE mutating anything. The commit decides from these copies which
	// edges are kept, added, and removed, and reassigns the dataset's own
	// lists to them; stored lists of other records (which may share backing
	// storage) are never resliced in place.
	current, existed := graph[dataset.Name]
	var oldParents, oldChildren []string
	if current != nil {
		oldParents = append(oldParents, current.Parents...)
		// Normalize the preserved downstream on the copy as well, so a
		// hand-edited unsorted or duplicated list is repaired without an
		// in-place write.
		oldChildren = uniqueSorted(current.Children)
	}

	// Adding an edge dataset -> parent creates a cycle exactly when parent
	// can already reach the dataset by following parent edges in the
	// post-replacement graph.
	for _, parent := range wanted {
		if reachesAfterReplacement(graph, dataset.Name, wanted, parent, dataset.Name) {
			return fmt.Errorf("%w: dataset %q cannot depend on %q, it would reach itself", ErrCycle, dataset.Name, parent)
		}
	}

	// ---- All checks passed; commit below this line. ----
	//
	// No name list is edited in place. An in-place removal
	// (append(list[:i], list[i+1:]...)) shifts the shared backing array and
	// corrupts every other record whose list shares that storage — the removed
	// name lands in a neighbor's window and a kept name can duplicate or
	// vanish. In-place insertion is equally unsafe when the list has spare
	// capacity another record's list occupies. withName and withoutName
	// allocate independent slices instead.

	if !existed || current == nil {
		current = &Lineage{Dataset: dataset.Name}
		graph[dataset.Name] = current
	}
	current.Parents = wanted
	current.Children = oldChildren

	newSet := toSet(wanted)
	oldSet := toSet(oldParents)

	// Dropped upstreams lose the dataset as a child. Every name list is
	// rewritten on a fresh slice (see withoutName): an in-place removal would
	// shift the shared backing array and corrupt another record's list that
	// happens to share that storage.
	for _, oldParent := range oldParents {
		if newSet[oldParent] {
			continue // relationship is kept; that record's list is not touched
		}
		if entry := graph[oldParent]; entry != nil {
			entry.Children = withoutName(entry.Children, dataset.Name)
		}
	}

	// Only newly added upstreams gain the dataset as a child, each listing it
	// exactly once. withName allocates a fresh slice, so spare capacity in the
	// stored list can never overwrite names another record's list occupies in
	// the same backing array. Kept upstreams already list the dataset and are
	// deliberately left alone, so an unrelated record sharing their list sees
	// no movement at all.
	for _, parent := range wanted {
		if oldSet[parent] {
			continue
		}
		entry := graph[parent]
		entry.Children = withName(entry.Children, dataset.Name)
	}

	return nil
}

// reachesAfterReplacement reports whether start can reach target by following
// parent edges. While walking, the parents of overrideNode are treated as
// overrideParents, which makes the traversal reflect the graph AS IT WILL BE
// after the pending registration rather than the graph being replaced.
func reachesAfterReplacement(graph map[string]*Lineage, overrideNode string, overrideParents []string, start, target string) bool {
	seen := map[string]bool{}
	var walk func(node string) bool
	walk = func(node string) bool {
		if node == target {
			return true
		}
		if seen[node] {
			return false
		}
		seen[node] = true

		var nextParents []string
		if node == overrideNode {
			nextParents = overrideParents
		} else if entry, ok := graph[node]; ok && entry != nil {
			nextParents = entry.Parents
		}
		for _, parent := range nextParents {
			if walk(parent) {
				return true
			}
		}
		return false
	}
	return walk(start)
}

// Roots lists datasets with no parents, sorted by name.
func Roots(graph map[string]*Lineage) []string {
	var roots []string
	for name, entry := range graph {
		if entry != nil && len(entry.Parents) == 0 {
			roots = append(roots, name)
		}
	}
	sort.Strings(roots)
	return roots
}

// uniqueSorted returns a sorted, duplicate-free copy of names. The result is
// nil when no name remains, so empty lineage stays empty.
func uniqueSorted(names []string) []string {
	if len(names) == 0 {
		return nil
	}
	seen := make(map[string]bool, len(names))
	out := make([]string, 0, len(names))
	for _, name := range names {
		if !seen[name] {
			seen[name] = true
			out = append(out, name)
		}
	}
	sort.Strings(out)
	return out
}

func toSet(names []string) map[string]bool {
	set := make(map[string]bool, len(names))
	for _, name := range names {
		set[name] = true
	}
	return set
}

// withName returns a NEW sorted, duplicate-free slice that is list with name
// inserted at its byte-order position. It never writes through list's backing
// array: that array may be shared with another record's name list (or may have
// spare capacity another record's window occupies), so an in-place insertion
// could overwrite names the other record still owns. Entries other than the
// insertion are copied verbatim; the returned slice has no spare capacity.
func withName(list []string, name string) []string {
	index := sort.SearchStrings(list, name)
	if index < len(list) && list[index] == name {
		// Already present; return an independent copy so callers can never
		// mutate a shared backing array through the result.
		return append([]string(nil), list...)
	}
	out := make([]string, 0, len(list)+1)
	out = append(out, list[:index]...)
	out = append(out, name)
	out = append(out, list[index:]...)
	return out
}

// withoutName returns a NEW sorted slice equal to list with name omitted (if
// present). Unlike an in-place append(list[:i], list[i+1:]...), it never
// shifts the original backing array, so removing a name from one record can
// not move or duplicate the names another record's list shares in the same
// storage. A list without the name — including one that becomes empty — is
// still returned as an independent slice (nil when empty, matching the
// package's empty-lineage convention).
func withoutName(list []string, name string) []string {
	index := sort.SearchStrings(list, name)
	if index >= len(list) || list[index] != name {
		return append([]string(nil), list...)
	}
	if len(list) == 1 {
		return nil
	}
	out := make([]string, 0, len(list)-1)
	out = append(out, list[:index]...)
	out = append(out, list[index+1:]...)
	return out
}

