355	// TestTraceReportCarriesContentIDAndQueryDeep pins, for a deep graph, that
356	// the report's identifiers come from the snapshot actually read and from the
357	// query as typed — never from whichever input record appeared first.
358	func TestTraceReportCarriesContentIDAndQueryDeep(t *testing.T) {
359		in := `{"datasets":[
360			{"name":"R","upstreams":[]},
361			{"name":"M","upstreams":["R"]},
362			{"name":"Z","upstreams":["M"]},
363			{"name":"A","upstreams":["Z"]},
364			{"name":"T","upstreams":["A"]}
365		]}`
366		snap := snapshotOf(t, in)
367		report, err := TraceSources(snap, "T")
368		if err != nil {
