1	package chainledger
2	
3	import (
4		"reflect"
5		"testing"
6	)
7	
8	// sharedCDList builds the headline alias graph without going through Register:
9	// A and B are roots, C and D both depend on A and B. Every record is
10	// independent, but A.Children and B.Children share one backing array
11	// ([C D]), just as two slices produced by reslicing the same storage do.
12	func sharedCDList() (map[string]*Lineage, *Lineage, *Lineage, *Lineage, *Lineage) {
13		shared := []string{"C", "D"}
14		a := &Lineage{Dataset: "A", Children: shared}
15		b := &Lineage{Dataset: "B", Children: shared}
16		c := &Lineage{Dataset: "C", Parents: append([]string(nil), "A", "B")}
17		d := &Lineage{Dataset: "D", Parents: append([]string(nil), "A", "B")}
18		graph := map[string]*Lineage{"A": a, "B": b, "C": c, "D": d}
19		return graph, a, b, c, d
20	}
21	
22	// TestRegisterSharedChildrenStorageRepoint is the headline fix: replacing C's
23	// upstreams with only B must leave A.Children == [D], B.Children == [C D],
24	// D.Parents == [A B], and C's own downstream records untouched — even though
25	// A and B's downstream lists share one backing array.
26	func TestRegisterSharedChildrenStorageRepoint(t *testing.T) {
27		graph, heldA, heldB, heldC, heldD := sharedCDList()
28	
29		if err := Register(graph, Dataset{Name: "C"}, []string{"B"}); err != nil {
30			t.Fatalf("Register(C, [B]) unexpected error: %v", err)
31		}
32		assertLineageConsistent(t, graph)
33	
34		if got := graph["C"].Parents; !reflect.DeepEqual(got, []string{"B"}) {
35			t.Errorf("C.Parents = %v, want [B]", got)
36		}
37		if got := graph["A"].Children; !reflect.DeepEqual(got, []string{"D"}) {
38			t.Errorf("A.Children = %v, want [D]", got)
39		}
40		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
41			t.Errorf("B.Children = %v, want [C D] (must not lose C or duplicate D)", got)
42		}
43		if got := graph["D"].Parents; !reflect.DeepEqual(got, []string{"A", "B"}) {
44			t.Errorf("D.Parents = %v, want [A B] (unrelated record must stay unchanged)", got)
45		}
46		if got := graph["C"].Children; len(got) != 0 {
47			t.Errorf("C.Children = %v, want empty", got)
48		}
49	
50		// Records the caller already held must read the same correct relations.
51		if got := heldA.Children; !reflect.DeepEqual(got, []string{"D"}) {
52			t.Errorf("held A record Children = %v, want [D]", got)
53		}
54		if got := heldB.Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
55			t.Errorf("held B record Children = %v, want [C D]", got)
56		}
57		if got := heldC.Parents; !reflect.DeepEqual(got, []string{"B"}) {
58			t.Errorf("held C record Parents = %v, want [B]", got)
59		}
60		if got := heldD.Parents; !reflect.DeepEqual(got, []string{"A", "B"}) {
61			t.Errorf("held D record Parents = %v, want [A B]", got)
62		}
63	}
64	
65	// TestRegisterSharedChildrenStorageKeepEdge checks that when the changed
66	// dataset keeps the edge into a list sharing storage with another node's list,
67	// neither list is mutated by in-place removal.
68	func TestRegisterSharedChildrenStorageKeepEdge(t *testing.T) {
69		graph, _, heldB, _, heldD := sharedCDList()
70	
71		// Replace C's parents with [A] (A kept, B dropped).
72		if err := Register(graph, Dataset{Name: "C"}, []string{"A"}); err != nil {
73			t.Fatalf("Register(C, [A]) unexpected error: %v", err)
74		}
75		assertLineageConsistent(t, graph)
76		if got := graph["A"].Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
77			t.Errorf("A.Children = %v, want [C D]", got)
78		}
79		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"D"}) {
80			t.Errorf("B.Children = %v, want [D]", got)
81		}
82		if got := heldB.Children; !reflect.DeepEqual(got, []string{"D"}) {
83			t.Errorf("held B record Children = %v, want [D]", got)
84		}
85		if got := heldD.Parents; !reflect.DeepEqual(got, []string{"A", "B"}) {
86			t.Errorf("held D record Parents = %v, want [A B]", got)
87		}
88	}
89	
90	// TestRegisterOverlappingChildrenSlices covers the partial-overlap variant:
91	// two child lists share only an interval of their backing storage (different
92	// lengths and offsets into the same array).
93	func TestRegisterOverlappingChildrenSlices(t *testing.T) {
94		// Backing array [C D E Z]: A's list is the [C D E] window and B's list
95		// is the [D E] window, so the two lists overlap on [D E].
96		backing := []string{"C", "D", "E", "Z"}
97		a := &Lineage{Dataset: "A", Children: backing[:3]}  // [C D E]
98		b := &Lineage{Dataset: "B", Children: backing[1:3]} // [D E]
99		c := &Lineage{Dataset: "C", Parents: []string{"A"}}
100		d := &Lineage{Dataset: "D", Parents: []string{"A", "B"}}
101		e := &Lineage{Dataset: "E", Parents: []string{"A", "B"}}
102		graph := map[string]*Lineage{"A": a, "B": b, "C": c, "D": d, "E": e}
103	
104		// C moves from A to B. A's list loses C, B's list gains C; the shared
105		// [D E] window must survive in both with no corruption.
106		if err := Register(graph, Dataset{Name: "C"}, []string{"B"}); err != nil {
107			t.Fatalf("Register(C, [B]) unexpected error: %v", err)
108		}
