111			t.Errorf("A.Children = %v, want [D E]", got)
112		}
113		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C", "D", "E"}) {
114			t.Errorf("B.Children = %v, want [C D E]", got)
115		}
