124	// TestRegisterAddIntoListWithSpareCapacity covers adding an edge into a child
125	// list that carries spare capacity: a second record's list may share that
126	// tail storage, so appending into the spare capacity must never overwrite a
127	// name the other record still uses.
128	func TestRegisterAddIntoListWithSpareCapacity(t *testing.T) {
129		// B.Children = [D] with two slots of spare capacity. A.Children aliases
130		// the tail window of the SAME backing array ([Y Z]), so the graph is
131		// consistent but an in-place append into B would overwrite A's names.
132		backing := make([]string, 3, 3)
133		backing[0] = "D"
134		backing[1] = "Y"
135		backing[2] = "Z"
