162	func TestRegisterMixedChangeWithSharedStorage(t *testing.T) {
163		// A and X currently list [C D] sharing storage; B lists [D]. C depends
164		// on A and X. Replace C's parents with [X B]: A loses C, X keeps C, B
165		// gains C. D keeps depending on A, X, and B... set D on A, X, B.
