196	// new dataset when both upstreams' child lists share backing storage: A and B
197	// both currently list only D, with spare capacity behind the shared window.
198	// Both must independently end up listing [C D]; the second insertion must not
199	// see the first one's write.
200	func TestRegisterNewDatasetIntoSharedChildLists(t *testing.T) {
201		backing := make([]string, 1, 3)
202		backing[0] = "D"
203		shared := backing[:1]
204		a := &Lineage{Dataset: "A", Children: shared}
205		b := &Lineage{Dataset: "B", Children: shared}
