210			t.Fatalf("Register(C, [A B]) unexpected error: %v", err)
211		}
212		assertLineageConsistent(t, graph)
213		if got := graph["A"].Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
214			t.Errorf("A.Children = %v, want [C D]", got)
215		}
216		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
