226		graph["A"].Children = append(graph["A"].Children, "leak")
227		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
228			t.Errorf("B.Children = %v, want [C D] after mutating A's list", got)
229		}
