281				t.Errorf("held C record Parents = %v, want [A B]", got)
282			}
283			if got := heldA.Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
284				t.Errorf("A.Children = %v, want [C D]", got)
285			}
286			if got := heldB.Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
287				t.Errorf("B.Children = %v, want [C D]", got)
