57	// plan with records, removal entries, and upstream names reordered, H's
58	// upstreams repeated, and extra JSON whitespace.
59	const convergenceShuffledPlanFile = `{"removals" : ["B", "M"], "changes":[
60		{"upstreams":["S","C","S","C"],"name":"H"},
