78	// parseBatchReport decodes a preview/apply stdout report.
79	func parseBatchReport(t *testing.T, stdout string) *chainledger.BatchReport {
80		t.Helper()
81		var report chainledger.BatchReport
82		if err := json.Unmarshal([]byte(stdout), &report); err != nil {
83			t.Fatalf("report stdout is not valid JSON: %v\n%s", err, stdout)
84		}
85		return &report
86	}
