88	// assertConvergenceSuccessReport pins the complete classification of the
89	// successful batch.
90	func assertConvergenceSuccessReport(t *testing.T, report *chainledger.BatchReport) {
91		t.Helper()
92		if got, want := report.RemovedDatasets, []string{"B", "M"}; !reflect.DeepEqual(got, want) {
93			t.Errorf("removedDatasets = %v, want %v", got, want)
94		}
95		if got, want := report.ChangedDatasets, []string{"C", "H"}; !reflect.DeepEqual(got, want) {
96			t.Errorf("changedDatasets = %v, want %v", got, want)
97		}
98		if len(report.NewDatasets) != 0 {
99			t.Errorf("newDatasets = %v, want []", report.NewDatasets)
100		}
101		// T is affected exactly once through the converging branches; H is a
102		// direct change and must not be listed here.
103		if got, want := report.AffectedDownstreams, []string{"T"}; !reflect.DeepEqual(got, want) {
104			t.Errorf("affectedDownstreams = %v, want %v", got, want)
105		}
106		if got, want := report.RemovedRelations, []chainledger.Relation{
107			{Upstream: "B", Downstream: "H"},
108			{Upstream: "M", Downstream: "B"},
109			{Upstream: "M", Downstream: "C"},
110			{Upstream: "R", Downstream: "M"},
111		}; !reflect.DeepEqual(got, want) {
112			t.Errorf("removedRelations = %v, want %v", got, want)
113		}
114		if got, want := report.AddedRelations, []chainledger.Relation{
115			{Upstream: "R", Downstream: "C"},
116			{Upstream: "S", Downstream: "H"},
117		}; !reflect.DeepEqual(got, want) {
118			t.Errorf("addedRelations = %v, want %v", got, want)
119		}
120		wantFinal := chainledger.GraphFile{Datasets: []chainledger.GraphDataset{
121			{Name: "C", Upstreams: []string{"R"}},
122			{Name: "H", Upstreams: []string{"C", "S"}},
123			{Name: "R", Upstreams: []string{}},
124			{Name: "S", Upstreams: []string{}},
125			{Name: "T", Upstreams: []string{"H"}},
126			{Name: "U", Upstreams: []string{}},
127			{Name: "V", Upstreams: []string{"U"}},
128		}}
129		if !reflect.DeepEqual(report.FinalGraph, wantFinal) {
130			t.Errorf("finalGraph = %+v, want %+v", report.FinalGraph, wantFinal)
131		}
132	}
