134	// TestCLISharedIntermediatePreviewIsReadOnly: preview prints the full success
135	// report but the graph file stays byte-for-byte as submitted — nodes and
136	// bidirectional relations untouched.
137	func TestCLISharedIntermediatePreviewIsReadOnly(t *testing.T) {
138		graphPath := writeFile(t, "graph.json", convergenceGraphFile)
139		planPath := writeFile(t, "plan.json", convergencePlanFile)
140		original := readFile(t, graphPath)
141	
142		stdout, stderr, exit := captureStdout(t, func() int {
143			return run([]string{"preview", graphPath, planPath})
144		})
145		if exit != 0 {
146			t.Fatalf("preview exit = %d, stderr = %s", exit, stderr)
147		}
148		assertConvergenceSuccessReport(t, parseBatchReport(t, stdout))
149	
150		if got := readFile(t, graphPath); got != original {
151			t.Fatalf("preview modified the graph file:\n got %s\nwant %s", got, original)
152		}
153	}
154	
155	// TestCLISharedIntermediateApplyWritesReportedFinalGraph: apply commits the
156	// batch; the graph rewritten to disk parses to exactly the finalGraph carried
157	// in the report, and the preview and apply reports are identical.
158	func TestCLISharedIntermediateApplyWritesReportedFinalGraph(t *testing.T) {
159		previewGraphPath := writeFile(t, "preview-graph.json", convergenceGraphFile)
160		planPath := writeFile(t, "plan.json", convergencePlanFile)
161		previewOut, stderr, exit := captureStdout(t, func() int {
162			return run([]string{"preview", previewGraphPath, planPath})
163		})
164		if exit != 0 {
165			t.Fatalf("preview exit = %d, stderr = %s", exit, stderr)
166		}
167		previewReport := parseBatchReport(t, previewOut)
168	
169		applyGraphPath := writeFile(t, "apply-graph.json", convergenceGraphFile)
170		applyOut, stderr, exit := captureStdout(t, func() int {
171			return run([]string{"apply", applyGraphPath, planPath})
172		})
173		if exit != 0 {
174			t.Fatalf("apply exit = %d, stderr = %s", exit, stderr)
175		}
176		applyReport := parseBatchReport(t, applyOut)
177		if !reflect.DeepEqual(previewReport, applyReport) {
178			t.Fatalf("preview and apply reports differ:\n preview=%#v\n apply=%#v", previewReport, applyReport)
179		}
180		assertConvergenceSuccessReport(t, applyReport)
181	
182		// The written graph file is exactly the report's final graph (and contains
183		// no trace of M or B).
184		written, err := chainledger.UnmarshalGraphFile([]byte(readFile(t, applyGraphPath)))
185		if err != nil {
186			t.Fatalf("written graph file is invalid: %v", err)
187		}
188		if _, ok := written["M"]; ok {
189			t.Errorf("M still present in written graph file")
190		}
191		if _, ok := written["B"]; ok {
192			t.Errorf("B still present in written graph file")
193		}
194		writtenReport, err := chainledger.MarshalGraphFile(written)
195		if err != nil {
196			t.Fatalf("marshal written graph: %v", err)
197		}
198		finalBytes, err := json.MarshalIndent(applyReport.FinalGraph, "", "  ")
199		if err != nil {
