201		}
202		if string(writtenReport) != string(finalBytes) {
203			t.Fatalf("written graph differs from report finalGraph:\n written:\n%s\n report:\n%s", writtenReport, finalBytes)
204		}
205		// The isolated U -> V component is intact in the written file.
206		if got := written["V"].Parents; !reflect.DeepEqual(got, []string{"U"}) {
207			t.Errorf("V.Parents = %v, want [U]", got)
208		}
209	}
