211	// TestCLISharedIntermediateDanglingReferenceRejectsBatch: when H is not
212	// repointed and still references deleted B, both preview and apply must fail,
213	// naming H and B, printing no success report, and leaving the graph file
214	// byte-for-byte untouched (so C's otherwise-legal repoint never lands).
215	func TestCLISharedIntermediateDanglingReferenceRejectsBatch(t *testing.T) {
216		for _, command := range []string{"preview", "apply"} {
217			t.Run(command, func(t *testing.T) {
218				graphPath := writeFile(t, "graph.json", convergenceGraphFile)
219				planPath := writeFile(t, "plan.json", convergenceDanglingPlanFile)
220				original := readFile(t, graphPath)
221	
222				stdout, stderr, exit := captureStdout(t, func() int {
223					return run([]string{command, graphPath, planPath})
224				})
225				if exit == 0 {
226					t.Fatalf("%s exit = 0, want non-zero for dangling H -> B", command)
227				}
228				if stdout != "" {
229					t.Errorf("%s stdout = %q, want empty on rejection", command, stdout)
230				}
231				if !strings.Contains(stderr, "H") || !strings.Contains(stderr, "B") {
232					t.Errorf("%s stderr = %q, want error naming referrer H and deleted B", command, stderr)
233				}
234				if got := readFile(t, graphPath); got != original {
235					t.Fatalf("%s modified the graph file on rejection:\n got %s\nwant %s", command, got, original)
236				}
237				// The preserved file still parses with C on M and H on B and C.
238				graph, err := chainledger.UnmarshalGraphFile([]byte(original))
239				if err != nil {
240					t.Fatalf("preserved graph file is invalid: %v", err)
241				}
242				if got := graph["C"].Parents; !reflect.DeepEqual(got, []string{"M"}) {
243					t.Errorf("C.Parents = %v, want [M] (legal repoint must not apply early)", got)
244				}
245				if got := graph["H"].Parents; !reflect.DeepEqual(got, []string{"B", "C"}) {
246					t.Errorf("H.Parents = %v, want [B C]", got)
247				}
248			})
249		}
250	}
251	
252	// TestCLISharedIntermediateDeterministicBytes: semantically identical graph
253	// and plan inputs that differ only in record order, upstream order, repeated
254	// upstreams, and JSON whitespace must produce byte-identical preview reports
255	// and byte-identical applied graph files.
256	func TestCLISharedIntermediateDeterministicBytes(t *testing.T) {
257		canonicalGraph := writeFile(t, "graph-canonical.json", convergenceGraphFile)
258		shuffledGraph := writeFile(t, "graph-shuffled.json", convergenceShuffledGraphFile)
259		canonicalPlan := writeFile(t, "plan-canonical.json", convergencePlanFile)
260		shuffledPlan := writeFile(t, "plan-shuffled.json", convergenceShuffledPlanFile)
261	
262		runPreview := func(graphPath, planPath string) string {
263			t.Helper()
264			stdout, stderr, exit := captureStdout(t, func() int {
265				return run([]string{"preview", graphPath, planPath})
266			})
267			if exit != 0 {
268				t.Fatalf("preview exit = %d, stderr = %s", exit, stderr)
269			}
270			return stdout
271		}
272		canonicalReport := runPreview(canonicalGraph, canonicalPlan)
273		assertConvergenceSuccessReport(t, parseBatchReport(t, canonicalReport))
274	
275		for name, paths := range map[string][2]string{
276			"shuffled plan only":    {canonicalGraph, shuffledPlan},
277			"shuffled graph only":   {shuffledGraph, canonicalPlan},
278			"shuffled graph & plan": {shuffledGraph, shuffledPlan},
279		} {
280			t.Run(name, func(t *testing.T) {
281				if got := runPreview(paths[0], paths[1]); got != canonicalReport {
282					t.Fatalf("preview bytes differ for semantically equal inputs:\n--- got ---\n%s\n--- want ---\n%s", got, canonicalReport)
283				}
284			})
285		}
286	
287		// Apply must also write byte-identical graph files.
288		applyGraph := writeFile(t, "graph-apply.json", convergenceShuffledGraphFile)
289		_, stderr, exit := captureStdout(t, func() int {
290			return run([]string{"apply", applyGraph, shuffledPlan})
291		})
292		if exit != 0 {
293			t.Fatalf("apply exit = %d, stderr = %s", exit, stderr)
294		}
295		// Apply the canonical inputs in a separate file and compare the on-disk
296		// bytes directly.
297		canonicalApplyGraph := writeFile(t, "graph-apply-canonical.json", convergenceGraphFile)
298		_, stderr, exit = captureStdout(t, func() int {
299			return run([]string{"apply", canonicalApplyGraph, canonicalPlan})
300		})
301		if exit != 0 {
302			t.Fatalf("canonical apply exit = %d, stderr = %s", exit, stderr)
303		}
304		if got, want := readFile(t, applyGraph), readFile(t, canonicalApplyGraph); got != want {
305			t.Fatalf("applied graph files differ:\n--- shuffled ---\n%s\n--- canonical ---\n%s", got, want)
306		}
307	}
