// reaches the same candidate on the candidate's shortest level — the one whose
// full path from the query is smallest. All such paths have equal length, so
// they are compared element by element from the START in UTF-8 byte order, at
// the first differing name: one step at a time up the shared parent-pointer
// tree. Two paths that have agreed through every position end together at the
// query (equal paths); the first mismatch decides, exactly as comparing the
// expanded name slices would. predecessors never repeats a name within a round
// (each predecessor node contributes once), so the first smallest name wins.
func bestPredecessor(predecessors []string, parent map[string]string) string {
	best := predecessors[0]
	for _, candidate := range predecessors[1:] {
		if routeLess(candidate, best, parent) {
