	if !reflect.DeepEqual(report.Sources, want) {
		t.Errorf("Sources = head %v tail %v, want a-rail path ending R",
			firstNames(report.Sources[0].Path, 4), lastNames(report.Sources[0].Path, 4))
	}
}

