// "bN" (larger) at every level; the representative path must then always take
// the a-rail, decided at the first differing name right after the query.
func convergingLadderJSON(levels int, multiRoot bool) string {
	json := `{"datasets":[`
	first := true
	emit := func(rec string) {
		if !first {
			json += ","
		}
		first = false
		json += rec
	}
	emit(`{"name":"T","upstreams":["a0","b0"]}`)
	for i := 0; i < levels; i++ {
		var upA, upB []string
		if i+1 < levels {
			upA = []string{fmt.Sprintf("a%d", i+1), fmt.Sprintf("b%d", i+1)}
			upB = upA
		} else if multiRoot {
			upA = []string{"M"}
			upB = []string{"M"}
		} else {
			upA = []string{"R"}
			upB = []string{"R"}
		}
		emit(fmt.Sprintf(`{"name":"a%d","upstreams":[%s]}`, i, quoteList(upA)))
		emit(fmt.Sprintf(`{"name":"b%d","upstreams":[%s]}`, i, quoteList(upB)))
	}
	if multiRoot {
		emit(`{"name":"M","upstreams":["R1","R2"]}`)
		emit(`{"name":"R1","upstreams":[]}`)
		emit(`{"name":"R2","upstreams":[]}`)
	} else {
		emit(`{"name":"R","upstreams":[]}`)
	}
	return json + `]}`
}

func quoteList(names []string) string {
	out := ""
	for i, name := range names {
		if i > 0 {
			out += ","
		}
		out += fmt.Sprintf("%q", name)
	}
	return out
}

